effect.shader:
// globais do Node ligados ao motor (tools/nodevideo/ligar_globais.py)
#define _viewport_ratio acProporcaoDoNode
vec4 u_xlat0;
vec4 u_xlat1;
bvec2 u_xlatb1;
vec4 u_xlat2;
vec4 u_xlat3;
vec4 u_xlat4;
vec4 u_xlat5;
bool u_xlatb6;
vec2 u_xlat12;
float u_xlat18;
bool u_xlatb18;
bool u_xlatb19;
void main()
{
    u_xlat0.xy = acScreenNorm.xy * vec2(_viewport_ratio.x, _viewport_ratio.y);
    u_xlat12.xy = (-_point1.xy) * vec2(_viewport_ratio.x, _viewport_ratio.y) + u_xlat0.xy;
    u_xlat12.x = dot(u_xlat12.xy, u_xlat12.xy);
    u_xlat12.x = sqrt(u_xlat12.x);
    u_xlatb18 = u_xlat12.x==0.0;
    u_xlat12.x = log2(u_xlat12.x);
    u_xlat12.x = u_xlat12.x * _blend;
    u_xlat12.x = exp2(u_xlat12.x);
    u_xlat12.x = float(1.0) / u_xlat12.x;
    u_xlat12.x = (u_xlatb18) ? 1.0 : u_xlat12.x;
    u_xlat1.xy = (-_point2.xy) * vec2(_viewport_ratio.x, _viewport_ratio.y) + u_xlat0.xy;
    u_xlat18 = dot(u_xlat1.xy, u_xlat1.xy);
    u_xlat18 = sqrt(u_xlat18);
    u_xlatb1.x = u_xlat18==0.0;
    u_xlat18 = log2(u_xlat18);
    u_xlat18 = u_xlat18 * _blend;
    u_xlat18 = exp2(u_xlat18);
    u_xlat18 = float(1.0) / u_xlat18;
    u_xlat18 = (u_xlatb1.x) ? 1.0 : u_xlat18;
    u_xlat1.xyz = vec3(u_xlat18) * _color2.xyz;
    u_xlat1.xyz = u_xlat12.xxx * _color1.xyz + u_xlat1.xyz;
    u_xlat12.x = u_xlat18 + u_xlat12.x;
    u_xlat2.xy = (-_point3.xy) * vec2(_viewport_ratio.x, _viewport_ratio.y) + u_xlat0.xy;
    u_xlat18 = dot(u_xlat2.xy, u_xlat2.xy);
    u_xlat18 = sqrt(u_xlat18);
    u_xlatb19 = u_xlat18==0.0;
    u_xlat18 = log2(u_xlat18);
    u_xlat18 = u_xlat18 * _blend;
    u_xlat18 = exp2(u_xlat18);
    u_xlat18 = float(1.0) / u_xlat18;
    u_xlat18 = (u_xlatb19) ? 1.0 : u_xlat18;
    u_xlat1.xyz = vec3(u_xlat18) * _color3.xyz + u_xlat1.xyz;
    u_xlat12.x = u_xlat18 + u_xlat12.x;
    u_xlat0.xy = (-_point4.xy) * vec2(_viewport_ratio.x, _viewport_ratio.y) + u_xlat0.xy;
    u_xlat0.x = dot(u_xlat0.xy, u_xlat0.xy);
    u_xlat0.x = sqrt(u_xlat0.x);
    u_xlatb6 = u_xlat0.x==0.0;
    u_xlat0.x = log2(u_xlat0.x);
    u_xlat0.x = u_xlat0.x * _blend;
    u_xlat0.x = exp2(u_xlat0.x);
    u_xlat0.x = float(1.0) / u_xlat0.x;
    u_xlat0.x = (u_xlatb6) ? 1.0 : u_xlat0.x;
    u_xlat1.xyz = u_xlat0.xxx * _color4.xyz + u_xlat1.xyz;
    u_xlat0.x = u_xlat0.x + u_xlat12.x;
    u_xlat0.xyz = u_xlat1.xyz / u_xlat0.xxx;
    u_xlat1.xyz = u_xlat0.xyz * vec3(0.305306017, 0.305306017, 0.305306017) + vec3(0.682171106, 0.682171106, 0.682171106);
    u_xlat1.xyz = u_xlat0.xyz * u_xlat1.xyz + vec3(0.0125228781, 0.0125228781, 0.0125228781);
    u_xlat2.xyz = u_xlat0.xyz * u_xlat1.xyz;
    u_xlat3 = texture(inputImg, acScreenNorm.xy);
    u_xlatb18 = int(_blend_mode)==1;
    u_xlat2.w = 1.0;
    u_xlat4 = u_xlat2 * u_xlat3;
    u_xlat1.xyz = u_xlat0.xyz * u_xlat1.xyz + u_xlat3.xyz;
    u_xlat1.w = u_xlat3.w;
    u_xlat0 = (bool(u_xlatb18)) ? u_xlat4 : u_xlat1;
    u_xlat1.xyz = u_xlat2.xyz;
    u_xlat0 = (int(_blend_mode) != 0) ? u_xlat0 : u_xlat1;
    if(int(_use_inner_mask) != 0) {
        u_xlatb1.xy = equal(ivec4(int(_show_inner_mask), int(_b_clip_mask), int(_show_inner_mask), int(_show_inner_mask)), ivec4(1, 1, 0, 0)).xy;
        u_xlat2 = (u_xlatb1.x) ? vec4(1.0, 0.0, 1.0, 1.0) : u_xlat0;
        u_xlat4 = texture(Mask, acScreenNorm.xy);
        u_xlat5 = (-u_xlat4) + vec4(1.0, 1.0, 1.0, 1.0);
        u_xlat3 = u_xlat3 * u_xlat5;
        u_xlat2 = u_xlat2 * u_xlat4 + u_xlat3;
        u_xlat1.x = u_xlat4.x * u_xlat2.w;
        fragColor.w = (u_xlatb1.y) ? u_xlat1.x : u_xlat2.w;
        fragColor.xyz = u_xlat2.xyz;
    } else {
        fragColor = u_xlat0;
    }
    return;
}
